#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,k;scanf("%d %d",&n,&k);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
int target=n-k,lo=0,hi=n-1;
while(lo<=hi){
long long p=a[(lo+hi)/2];
int i=lo,j=hi;
while(i<=j){
while(a[i]<p)++i;
while(a[j]>p)--j;
if(i<=j){swap(a[i],a[j]);++i;--j;}}
if(target<=j)hi=j;else if(target>=i)lo=i;else break;}
printf("%lld\n",a[target]);return 0;}

